mapper.select:
select
c.C_Name as peCompanyName, c.C_Name_History as peCompanyNameHistory, unit.C_Name as peUnitName, pc.C_Name as pBuildUnitName, c.C_Abbreviation as peCompanyAbbName, unit.C_Abbreviation as peUnitAbbName, pc.C_Abbreviation as pConsAbbName, prod.D_Name as pCompDepName, case when p.Pe_Contract_Category='02' then sr.Sc_Name else con.con_Name end as conName, case when p.Pe_Contract_Category='02' then sr.Sc_Money else con.con_Money_Total end as conMoneyTotal, case when p.Pe_Contract_Category='02' then sr.Sc_Type else con.con_Type end as conType, case when p.Pe_Contract_Category='02' then sr.Sc_Code else con.con_Code end as conCode, pro.P_Name_History as pNameHistory, pro.P_Name as pName,
from Pe_Result pe left join Pe_Info p on pe.pe_id=p.Pe_id left join Con_Contract con on p.Pe_Con_Id=con.Con_Id left join Pre_Project pro on pro.P_Id=p.Pe_Project_Id left join SYS_Company c on c.C_Id=p.Pe_Company_Id left join SYS_Company unit on unit.C_Id=p.Pe_Unit_Id left join SYS_Company pc on pc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join Subcontract_Record sr on p.Pe_Sub_Contract=sr.Sc_Id
and p.Te_Id = #{params.teId}
and p.Pe_Project_Id=#{params.pId}
and pe.R_Delivery_Status=#{params.rDeliveryStatus}
and pe.R_Sign_State=#{params.rSignState}
and pe.R_Sign_Content like concat('%',#{params.rSignContent},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
order by pe.${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}

select count(1) from Pe_Result pe left join Pe_Info p on pe.pe_id=p.Pe_id left join Con_Contract con on p.Pe_Con_Id=con.Con_Id left join Pre_Project pro on pro.P_Id=p.Pe_Project_Id left join SYS_Company c on c.C_Id=p.Pe_Company_Id left join SYS_Company unit on unit.C_Id=p.Pe_Unit_Id left join SYS_Company pc on pc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department
and p.Te_Id = #{params.teId}
and p.Pe_Project_Id=#{params.pId}
and pe.R_Delivery_Status=#{params.rDeliveryStatus}
and pe.R_Sign_State=#{params.rSignState}
and pe.R_Sign_Content like concat('%',#{params.rSignContent},'%')
and con.Con_Name like concat('%',#{params.conName},'%')

mapper.update:
update Pe_Info_Collect_Dtl
set

    pec_Id=#{pecId}


    pec_Id=null


    1=1 and
    
        pecd_Id= #{item}
